"""A Class for performing sequenced interactions to dicom import patient data in the Monaco application"""
import interops.libraries.monaco.interactions.dicom_import as dcm_import
import time

class DicomImport():
    """
    Page Object Class for the DICOM Import dialog in Monaco.
    """
    def __init__(self) -> None:
        dcm_import.await_dicom_import_dialog()

    def do_browse(self, dicom_data_path:str):
        """
        Do browse for a patient given the dicom data path.

        :param: dicom_data_path (str), the source path of patient dicom data.
        """

        dcm_import.browse_directly(dicom_data_path)
        ##or the following, but it needs the setting in uiautomation.ext to a lower priority(e.g.,-10)
        #dcm_import.browse_by_clicks(dicom_data_path)
        ##or simply if path is "c:\\jdcom"
        #dicom_import.browse_folder()
        dcm_import.await_browse_done()

    def import_patient(self, patient_id:str, study_id: str,  image_set: str, structure_set: str, installation: str,
        clinic: str, imageset_destination: str, ct_to_ed: str, show_log_view: bool, minimized_logviewer: bool,
        delete_after_import: bool,  remove_selection_option:int, replace_if_existing: bool):
        """
        Import the data of a give patient.

        :params:
            patient_id (str), the patient id to import
            study_id (str), the study_id to choose
            image_set (str), the image set to select
            structure_set (str), the structure set to select
            installation (str), the installation to which the patient data will go
            clinic (str), the clinic location to which the patient data will go
            ct_to_ed (str), the ct to ed type to select
            show_log_view (bool), the option to show logviewer, True: show, False: not show.
            minimized_logviewer (bool), the option to minimize the logviewer, only valid if show_log_view is True.
            delete_after_import (bool), the option to delete after import, True: delete, False: not delete
            remove_selection_option (int), the option to remove slice from selections. 1:Odd, 2:Even, 3:As selected, otherv value: no remove.
            replace_if_existing(bool), the option to replace the existing data if existing, True: Replace, False: Combine.
        """
        dcm_import.select_patient_id(patient_id)
        time.sleep(5)
        logviewer_hwnd = dcm_import.enable_log(minimized_logviewer) if show_log_view else 0
        #CommonActions.left_click_object(MonacoDicomImportObjects.dICOM_Import_Tree)
        dcm_import.set_patient_and_study(patient_id, study_id)
        dcm_import.choose_imageset(image_set, False)
        dcm_import.choose_rtss(structure_set, True)
        time.sleep(3)
        if len(imageset_destination) > 0:
            dcm_import.unselect_imageset(image_set, True)
        dcm_import.select_installation(installation)
        dcm_import.select_clinic(clinic)
        customized_imageset_destination = len(imageset_destination) != 0
        if customized_imageset_destination:
            dcm_import.select_image_set_destination(imageset_destination)
        dcm_import.add_selection()
        if  not customized_imageset_destination or imageset_destination == "New Instance":
            dcm_import.select_ct_to_ed(ct_to_ed)
        dcm_import.toggle_delete_after_import(delete_after_import)

        if remove_selection_option == 1:
            dcm_import.remove_odd()
        elif remove_selection_option == 2:
            dcm_import.remove_even()
        elif remove_selection_option == 3:
            dcm_import.remove_selected()
        dest_patient_id = "1~" + patient_id
        dcm_import.store_dest_imageset_id(dest_patient_id, study_id)
        dcm_import.click_import_button(which_button = 0 if not customized_imageset_destination else 1 if not replace_if_existing else 2)
        if show_log_view and minimized_logviewer:
            dcm_import.CommonActions.restore_window(logviewer_hwnd)
        dcm_import.click_close_button()

    def get_dest_imageset_id(self) -> str:
        """
        Retrieve the stored destination imageset id

        :return: the destination imageset id stored in patient_data_registry
        """
        return dcm_import.get_dest_imageset_id()

